const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const needles = ee.Geometry.Point([-114.6139, 34.8483]); // Needles, California
  const startDate = '2017-06-15';
  const endDate = '2017-06-22'; // GEE date range is exclusive of the end date

  // 2. Data Acquisition & Check
  // NLDAS provides hourly near-surface air temperature.
  const collection = ee.ImageCollection('NLDAS/NLDAS_FORA0125_H')
    .filterDate(startDate, endDate)
    .filterBounds(needles)
    .select('temperature');

  const collectionSize = collection.size().getInfo();
  if (collectionSize === 0) {
    console.log("Evidence: No NLDAS images found for the specified date and location.");
    console.log("A: Yes");
    return;
  }
  console.log(`Image Count: ${collectionSize}`);

  // 3. Processing
  // Find the maximum temperature recorded at any hour during the period.
  const maxTempImage = collection.max();

  // 4. Calculation
  // Reduce to a single value at the point of interest.
  // Using a small scale since it's a point, but keeping it reasonable for a gridded product.
  const maxTempKelvinDict = maxTempImage.reduceRegion({
    reducer: ee.Reducer.first(),
    geometry: needles,
    scale: 1000, // NLDAS native resolution is ~12.5km
    maxPixels: 1e9
  });

  const maxTempKelvin = maxTempKelvinDict.get('temperature').getInfo();

  // 5. Validation & Final Answer
  if (maxTempKelvin === null || maxTempKelvin === undefined) {
    console.log("Evidence: Could not extract a temperature value from the data.");
    console.log("C3");
    return;
  }

  // Convert Kelvin to Fahrenheit: (K - 273.15) * 9/5 + 32
  const maxTempFahrenheit = (maxTempKelvin - 273.15) * 9 / 5 + 32;

  console.log(`Maximum Temperature (Kelvin): ${maxTempKelvin.toFixed(2)}`);
  console.log(`Maximum Temperature (Fahrenheit): ${maxTempFahrenheit.toFixed(2)}`);

  const thresholdFahrenheit = 115;
  console.log(`Threshold (Fahrenheit): ${thresholdFahrenheit}`);

  if (maxTempFahrenheit >= thresholdFahrenheit) {
    console.log("A: Yes");
  } else {
    console.log("B: No");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
